  @state ctx, gridFont, uiFont = gui.ctx, gui.font, gui.uiFont  @ 71
  @state dragging = false  @ 72   -- tracker-grid selection drag: click → held → release
  @state laneConsumed = false  @ 74
  @state paintLast = nil  @ 76   -- region-paint per-cell debounce
  @state renderFns = {  @ 186
  @state VNAME_MAX = 14  @ 302
